function parseSessionFile(filename) {
    const filePath = path.join(scratch, filename);
    if (!fs.existsSync(filePath)) return;
    const buf = fs.readFileSync(filePath);
    console.log(`\n========================================`);
    console.log(`Parsing ${filename} (${buf.length} bytes)`);
