const fs = require('fs');
const path = require('path');

const histPath = 'C:\\Users\\lg\\.gemini\\antigravity\\brain\\44470555-939d-4160-8744-09bb2f099064\\scratch\\History.db';
const buf = fs.readFileSync(histPath);

console.log('History file size:', buf.length);

// In Chrome/Edge History, urls table has:
// id, url, title, visit_count, typed_count, last_visit_time, hidden
// Let's search for records in SQLite leaf pages (0x0D).
const pageSize = buf.readUInt16BE(16);
console.log('Page size:', pageSize);

// Helper to read varint
function readVarint(buffer, offset) {
    let res = 0n;
    let bytesRead = 0;
    for (let i = 0; i < 9; i++) {
        const b = buffer[offset + i];
        bytesRead++;
        if (i === 8) {
            res = (res << 8n) | BigInt(b);
            break;
        }
        res = (res << 7n) | BigInt(b & 0x7F);
        if ((b & 0x80) === 0) break;
    }
    return { value: Number(res), rawBig: res, bytesRead };
}

const entries = [];

for (let pageOffset = 0; pageOffset < buf.length; pageOffset += pageSize) {
    const pageType = buf[pageOffset];
    if (pageType !== 0x0D) continue; // Leaf table page

    const numCells = buf.readUInt16BE(pageOffset + 3);
    for (let c = 0; c < numCells; c++) {
        const cellPtr = buf.readUInt16BE(pageOffset + 8 + c * 2);
        let ptr = pageOffset + cellPtr;
        if (ptr >= buf.length) continue;

        // Payload size
        const pSize = readVarint(buf, ptr);
        ptr += pSize.bytesRead;
        // Rowid
        const rowId = readVarint(buf, ptr);
        ptr += rowId.bytesRead;

        const payloadStart = ptr;
        // Header size
        const hSize = readVarint(buf, ptr);
        let hPtr = ptr + hSize.bytesRead;
        const headerEnd = payloadStart + hSize.value;

        const serialTypes = [];
        while (hPtr < headerEnd) {
            const st = readVarint(buf, hPtr);
            serialTypes.push(st.value);
            hPtr += st.bytesRead;
        }

        // Now read columns
        let bodyPtr = headerEnd;
        const cols = [];
        for (const st of serialTypes) {
            if (st === 0) {
                cols.push(null);
            } else if (st === 1) {
                cols.push(buf.readInt8(bodyPtr));
                bodyPtr += 1;
            } else if (st === 2) {
                cols.push(buf.readInt16BE(bodyPtr));
                bodyPtr += 2;
            } else if (st === 3) {
                // 3 byte int
                const v = (buf[bodyPtr] << 16) | (buf[bodyPtr+1] << 8) | buf[bodyPtr+2];
                cols.push(v);
                bodyPtr += 3;
            } else if (st === 4) {
                cols.push(buf.readInt32BE(bodyPtr));
                bodyPtr += 4;
            } else if (st === 5) {
                // 6 byte int
                bodyPtr += 6;
                cols.push(0);
            } else if (st === 6) {
                // 8 byte int (often last_visit_time: WebKit microseconds since 1601-01-01)
                const high = buf.readUInt32BE(bodyPtr);
                const low = buf.readUInt32BE(bodyPtr + 4);
                const val = BigInt(high) * 0x100000000n + BigInt(low);
                cols.push(val);
                bodyPtr += 8;
            } else if (st === 7) {
                cols.push(buf.readDoubleBE(bodyPtr));
                bodyPtr += 8;
            } else if (st === 8) {
                cols.push(0);
            } else if (st === 9) {
                cols.push(1);
            } else if (st >= 12 && st % 2 === 0) {
                // Blob
                const len = (st - 12) / 2;
                bodyPtr += len;
                cols.push(null);
            } else if (st >= 13 && st % 2 === 1) {
                // String
                const len = (st - 13) / 2;
                const str = buf.toString('utf8', bodyPtr, bodyPtr + len);
                cols.push(str);
                bodyPtr += len;
            } else {
                break;
            }
        }

        // Check if this looks like urls row: [id, url, title, visit_count, typed_count, last_visit_time, ...]
        if (cols.length >= 6 && typeof cols[0] === 'string' && cols[0].startsWith('http')) {
            // cols[0] = url, cols[1] = title
            const url = cols[0];
            const title = cols[1] || '';
            const lastTimeBig = typeof cols[4] === 'bigint' ? cols[4] : (typeof cols[5] === 'bigint' ? cols[5] : 0n);
            // WebKit timestamp to JS Date: (microsecs - 11644473600000000) / 1000
            let date = null;
            if (lastTimeBig > 11644473600000000n) {
